    align-items: center;

`

export const BodyContainer = styled.div`
    width: 70%;
    margin-top: 2rem;
    
`
export const TitleContainer = styled.div`
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;

